module layout

import math
import svg

// Bound the native serialized path, including Bezier controls and the conic
// controls generated by SVG arcs. The caller validates paint and stroke kinds;
// complex stroked outlines cannot use this fill/independent-line envelope.
pub fn paint_svg_path_native_ink_bounds(command &PaintCommand) ?LayoutRect {
	data := command.svg_data
	stride := compatibility_clip_path_segment_stride
	if data == unsafe { nil } || data.path_data.len < stride
		|| data.path_data.len % stride != 0 || data.path_data[0] !in [f32(0), 6] {
		return none
	}
	for value in data.path_data {
		if math.is_nan(f64(value)) || math.is_inf(f64(value), 0) || math.abs(value) > 1_000_000 {
			return none
		}
	}
	mut bounds := SVGPathBounds{}
	mut current := svg.Point{}
	mut subpath := svg.Point{}
	mut has_move := false
	mut arc_origin_known := true
	for offset := 0; offset < data.path_data.len; offset += stride {
		kind := data.path_data[offset]
		endpoint := svg.Point{f64(data.path_data[offset + 1]), f64(data.path_data[offset + 2])}
		match kind {
			0 {
				current = endpoint
				subpath = endpoint
				has_move = true
				arc_origin_known = true
				bounds = bounds.including(endpoint)
			}
			1 {
				bounds = bounds.including(current).including(endpoint)
				current = endpoint
				arc_origin_known = true
			}
			2, 3 {
				bounds = bounds.including(current).including(endpoint)
				count := if kind == 3 { 2 } else { 1 }
				for point in 0 .. count {
					bounds = bounds.including(svg.Point{f64(data.path_data[offset + 3 + point * 2]), f64(data.path_data[offset + 4 + point * 2])})
				}
				current = endpoint
				arc_origin_known = true
			}
			4 {
				if !arc_origin_known { return none }
				rx := f64(data.path_data[offset + 7])
				ry := f64(data.path_data[offset + 8])
				if (rx != 0 && math.abs(rx) < 0.0001) || (ry != 0 && math.abs(ry) < 0.0001) {
					return none
				}
				bounds = include_svg_arc_extrema(bounds, current, endpoint, rx, ry,
					f64(data.path_data[offset + 9]) * 180 / math.pi, data.path_data[offset + 10] != 0, data.path_data[offset + 11] != 0)
				current = endpoint
			}
			5 {
				bounds = bounds.including(current).including(subpath)
				current = subpath
				arc_origin_known = has_move
			}
			6 {
				bounds = bounds.including(endpoint).including(svg.Point{f64(data.path_data[offset + 3]), f64(data.path_data[offset + 4])})
				arc_origin_known = false
			}
			else { return none }
		}
	}
	rect := bounds.rect() or { return none }
	outset := if command.stroke_color != '' {
		math.max(f64(0), command.stroke_width)
	} else {
		f64(0)
	}
	normalized := PaintCommand{
		...*command
		kind:      'fill_rect'
		x:         rect.x - outset
		y:         rect.y - outset
		width:     rect.width + 2 * outset
		height:    rect.height + 2 * outset
		transform: multiply_affine(command.transform, data.path_transform)
	}
	return paint_leaf_native_ink_bounds(&normalized)
}
